def verify_lte_attach_call_flow(messages, logger, specyfic_logger):
    """
    SPHINX_IGNORE:
    [Documentation]   FUNCTION:verify_lte_attach_call_flow
    Metadata:
    | Version | Status  | Date | Author  | Change Notification |
    | 0.9 | DRAFT | 13.04.2016 | Grzegorz Kaczor  | Initial Version |
    | 0.9.1 | READY_FOR_REVIEW | 21.07.2016 | Grzegorz Kaczor | Internal_test_PASS |
    End of Metadata
    SPHINX_IGNORE

    Argument method to be used for verification of standard LTE attach call flow.
    Method looks for the last occurence of RRC Connection Setup message in given list of messages, from that point it looks for:
    RRC Connection Setup Complete
    RRC Connection Reconfiguration
    RRC Connection Reconfiguration Complete
    EMM Attach Accept
    messages.
    If not all messages are found it raises an call_flow_exceptions.AttachVerificationException.

    :param messages:    messages to be used for verifying attach call flow
    :type messages:     list
    :return:            None
    """
    try:
        logger.info("Messages to verify attach: {} ---> {}".format(str(messages)[1:30],
                                                                   "rest of the log available in QXDM_parsed_log.log"))
        specyfic_logger.debug("Messages to verify attach: {}".format(json.dumps(messages, indent=4, sort_keys=True)))
    except TypeError:
        logger.info("Messages to verify attach: {}".format(messages))
    index = _check_rrc_conn_req(messages)

    logger.info("RRC Connection Request message found")

    rrc_connection_setup = None
    rrc_connection_setup_complete = None
    rrc_connection_reconfiguration = None
    rrc_connection_reconfiguration_complete = None
    emm_attach_accept = None

    for i in range(index, len(messages)):
        rrc_connection_setup = _check_rrc_connection_setup(messages[i], rrc_connection_setup, logger)
        rrc_connection_setup_complete = _check_rrc_connection_setup_complete(messages[i],
                                                                             rrc_connection_setup_complete,
                                                                             logger)
        rrc_connection_reconfiguration = _check_rrc_connection_reconfiguration(messages[i],
                                                                               rrc_connection_reconfiguration,
                                                                               logger)
        rrc_connection_reconfiguration_complete = _check_rrc_connection_reconfiguration_complete(messages[i],
                                                                                                 rrc_connection_reconfiguration_complete,
                                                                                                 logger)
        emm_attach_accept = _check_emm_attach_accept(messages[i], emm_attach_accept, logger)

        if rrc_connection_setup and rrc_connection_setup_complete and rrc_connection_reconfiguration \
                and rrc_connection_reconfiguration_complete and emm_attach_accept:
            logger.info("Attach verification completed successfully")
            return

    expected_messages = {'RRCConnectionSetup': rrc_connection_setup,
                         'RRCConnectionSetupComplete': rrc_connection_setup_complete,
                         'RRCConnectionReconfiguration': rrc_connection_reconfiguration,
                         'RRCConnectionReconfigurationComplete': rrc_connection_reconfiguration_complete,
                         'Attach_accept': emm_attach_accept}

    not_found_messages = []
    for message_type, msg in list(expected_messages.items()):
        if msg is None:
            not_found_messages.append(message_type)

    raise call_flow_exceptions.AttachVerificationException("Could not find the correct message flow indicating ATTACH. "
                                                           "Messages not found: %s" % not_found_messages)


